const listPartyLedgerLines = `-- name: ListPartyLedgerLines :many
SELECT je.id AS entry_id, je.entry_number, je.created_at AS entry_date, je.narration,
       a.code AS account_code, a.name AS account_name,
       jl.debit_amount, jl.credit_amount, jl.currency, jl.description
FROM journal_lines jl
JOIN journal_entries je ON je.id = jl.journal_id
JOIN accounts a ON a.id = jl.account_id
WHERE je.tenant_id = $1 AND jl.party_id = $2 AND je.status = 'posted'
ORDER BY je.created_at ASC, je.entry_number ASC, jl.id ASC
`

type ListPartyLedgerLinesParams struct {
	TenantID uuid.UUID   `json:"tenant_id"`
	PartyID  pgtype.UUID `json:"party_id"`
}

type ListPartyLedgerLinesRow struct {
	EntryID      uuid.UUID      `json:"entry_id"`
	EntryNumber  string         `json:"entry_number"`
	EntryDate    time.Time      `json:"entry_date"`
	Narration    string         `json:"narration"`
	AccountCode  string         `json:"account_code"`
	AccountName  string         `json:"account_name"`
	DebitAmount  pgtype.Numeric `json:"debit_amount"`
	CreditAmount pgtype.Numeric `json:"credit_amount"`
	Currency     string         `json:"currency"`
	Description  pgtype.Text    `json:"description"`
}

// Lines tagged to a party on posted entries, oldest first. Filtered by tenant
// through the entry.
func (q *Queries) ListPartyLedgerLines(ctx context.Context, arg ListPartyLedgerLinesParams) ([]ListPartyLedgerLinesRow, error) {
	rows, err := q.db.Query(ctx, listPartyLedgerLines, arg.TenantID, arg.PartyID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPartyLedgerLinesRow{}
	for rows.Next() {
		var i ListPartyLedgerLinesRow
		if err := rows.Scan(
			&i.EntryID,
			&i.EntryNumber,
			&i.EntryDate,
			&i.Narration,
			&i.AccountCode,
			&i.AccountName,
			&i.DebitAmount,
			&i.CreditAmount,
			&i.Currency,
			&i.Description,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const nextBankAccountCode = `-- name: NextBankAccountCode :one
SELECT COALESCE(MAX(c), 0)::int AS max_code
FROM (
    SELECT code::int AS c
    FROM accounts
    WHERE tenant_id = $1 AND code ~ '^1[0-9]{3}$'
) AS codes
`

// Highest existing 1xxx asset-range code for the tenant, as an int. Caller adds
// the step. Returns 0 when the tenant has no codes in the range.
func (q *Queries) NextBankAccountCode(ctx context.Context, tenantID uuid.UUID) (int32, error) {
	row := q.db.QueryRow(ctx, nextBankAccountCode, tenantID)
	var max_code int32
	err := row.Scan(&max_code)
	return max_code, err
}

const nextJournalEntrySeq = `-- name: NextJournalEntrySeq :one
INSERT INTO journal_entry_counters (tenant_id, year, next_seq)
VALUES ($1, $2, 1)
ON CONFLICT (tenant_id, year) DO UPDATE
    SET next_seq = journal_entry_counters.next_seq + 1
RETURNING next_seq
`

type NextJournalEntrySeqParams struct {
	TenantID uuid.UUID `json:"tenant_id"`
	Year     int32     `json:"year"`
}

func (q *Queries) NextJournalEntrySeq(ctx context.Context, arg NextJournalEntrySeqParams) (int32, error) {
	row := q.db.QueryRow(ctx, nextJournalEntrySeq, arg.TenantID, arg.Year)
	var next_seq int32
	err := row.Scan(&next_seq)
	return next_seq, err
}

